import java.util.*;

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        boolean[][] settled = new boolean[n][n];
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[0]));
        heap.offer(new int[] {grid[0][0], 0, 0});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!heap.isEmpty()) {
            int[] current = heap.poll();
            int time = current[0];
            int r = current[1];
            int c = current[2];
            if (settled[r][c]) {
                continue;
            }
            settled[r][c] = true;
            if (r == n - 1 && c == n - 1) {
                return time;
            }

            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || settled[nr][nc]) {
                    continue;
                }
                heap.offer(new int[] {Math.max(time, grid[nr][nc]), nr, nc});
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        int low = Math.max(grid[0][0], grid[n - 1][n - 1]);
        int high = n * n - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canReach(grid, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canReach(int[][] grid, int limit) {
        int n = grid.length;
        if (grid[0][0] > limit) {
            return false;
        }
        boolean[][] visited = new boolean[n][n];
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[] {0, 0});
        visited[0][0] = true;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];
            if (r == n - 1 && c == n - 1) {
                return true;
            }
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || visited[nr][nc]) {
                    continue;
                }
                if (grid[nr][nc] <= limit) {
                    visited[nr][nc] = true;
                    stack.push(new int[] {nr, nc});
                }
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        int total = n * n;
        int[][] position = new int[total][2];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                position[grid[r][c]][0] = r;
                position[grid[r][c]][1] = c;
            }
        }

        UnionFind uf = new UnionFind(total);
        boolean[][] active = new boolean[n][n];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int time = 0; time < total; time++) {
            int r = position[time][0];
            int c = position[time][1];
            active[r][c] = true;
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && active[nr][nc]) {
                    uf.union(r * n + c, nr * n + nc);
                }
            }
            if (uf.connected(0, total - 1)) {
                return time;
            }
        }
        return -1;
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }

        boolean connected(int a, int b) {
            return find(a) == find(b);
        }
    }
}

import java.util.*;

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        if (n == 1) {
            return grid[0][0];
        }

        List<int[]> edges = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int id = r * n + c;
                if (r + 1 < n) {
                    edges.add(new int[] {Math.max(grid[r][c], grid[r + 1][c]), id, (r + 1) * n + c});
                }
                if (c + 1 < n) {
                    edges.add(new int[] {Math.max(grid[r][c], grid[r][c + 1]), id, r * n + c + 1});
                }
            }
        }
        edges.sort(Comparator.comparingInt(edge -> edge[0]));

        UnionFind uf = new UnionFind(n * n);
        for (int[] edge : edges) {
            uf.union(edge[1], edge[2]);
            if (uf.connected(0, n * n - 1)) {
                return edge[0];
            }
        }
        return -1;
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            Arrays.fill(size, 1);
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        boolean connected(int a, int b) {
            return find(a) == find(b);
        }
    }
}
